// Create an iterator
const myIterator = Iterator.from([32, 33, 16, 40]);
// Filter the iterator
const filteredIterator = myIterator.filter(x => x > 18);

---

// Create an iterator
const myIterator = Iterator.from([3, 10, 18, 30, 20]);
